<script setup lang="ts">
import type { MapLocation, WorldRecord } from '~/utils/geography/types'
const emit=defineEmits<{locate:[location:MapLocation]}>()
const kind=ref('all')
const {items:records,categories,total,pending,error,hasMore,load}=useGeographyContent('records',{category:kind,limit:6})
</script>
<template><section id="globe-records" class="geo-section" aria-labelledby="geo-records-title"><header><p class="geo-kicker">ՄՈԼՈՐԱԿԻ ԾԱՅՐԱՀԵՂՈՒԹՅՈՒՆՆԵՐԸ</p><h2 id="geo-records-title">Աշխարհի ռեկորդներ</h2><p>Յուրաքանչյուր ռեկորդ ունի իր չափանիշը։ «Ամենաբարձրը», «ամենամեծը» և «ամենախորը» տարբեր հարցերի պատասխաններ են։</p></header><div class="geo-filters" role="group" aria-label="Ռեկորդների կատեգորիաներ"><button class="geo-button" :aria-pressed="kind==='all'" @click="kind='all'">Բոլորը</button><button v-for="c in categories" :key="c.id" class="geo-button" :aria-pressed="kind===c.id" @click="kind=c.id">{{c.title}}</button></div><p v-if="pending" role="status">Բեռնում ենք ռեկորդները…</p><p v-if="error" role="alert">Տվյալները չբեռնվեցին։ <button class="geo-button" @click="load()">Կրկին փորձել</button></p><p class="geo-note" role="status">{{records.length}} / {{total}} ռեկորդ</p><div class="geo-grid"><article v-for="r in records" :id="r.id" :key="r.id" class="panel geo-card"><p class="geo-kicker">{{r.location}}</p><h3>{{r.title}}</h3><p class="geo-value">{{r.measure}}</p><details><summary>Իմանալ ավելին</summary><p>{{r.detail}}</p><p class="geo-note">Նշիչը ներկայացնում է օբյեկտի մոտավոր դիրքը․ տարածական օբյեկտի ամբողջ սահմանը չէ։</p><a class="geo-source" :href="r.source.url" target="_blank" rel="noopener noreferrer">{{r.source.name}} ↗</a></details><div class="geo-actions"><button v-if="r.coordinates" class="geo-button" @click="emit('locate',{coordinates:r.coordinates,label:r.measure})">Ցույց տալ երկրագնդի վրա ↗</button></div></article></div><div v-if="hasMore" class="geo-actions"><button class="geo-button" :disabled="pending" @click="load(true)">Հաջորդ 6 ռեկորդները ↓</button></div></section></template>
